insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25681')::uuid, md5('building-neuer-wall-80-20354')::uuid, '25681', 'hochwertige-bueroflaeche-im-bornholdhaus-25681', 'Hochwertige Bürofläche im Bornholdhaus', 'Das Bornholdhaus befindet sich in bester Innenstadtlage zwischen Neuem Wall und Bleichenfleet. Dank der fußläufig erreichbaren U-Bahnstationen Jungfernstieg und Stadthausbrücke …', 'Das Bornholdhaus befindet sich in bester Innenstadtlage zwischen Neuem Wall und Bleichenfleet. Dank der fußläufig erreichbaren U-Bahnstationen Jungfernstieg und Stadthausbrücke sowie mehrerer Buslinien ist eine hervorragende Anbindung an den öffentlichen Nahverkehr gewährleistet. Das direkte Umfeld ist von exklusiven Geschäften und Boutiquen geprägt und bietet zudem eine abwechslungsreiche Gastronomie.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25681-1')::uuid, md5('property-25681')::uuid, 'Mietfläche', 422, 35.5, null, 'filemaker', '25681-1') on conflict (id) do nothing;
