insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25602')::uuid, md5('building-holzdamm-28-32-20099')::uuid, '25602', 'das-pacific-haus-zwischen-hotel-atlantik-und-hauptbahnhof-25602', 'Das Pacific Haus zwischen Hotel Atlantik und Hauptbahnhof', 'Das mit dem Architekturpreis ausgezeichnete Bürogebäude verbindet in gelungener Weise die Kombination aus Funktionalität und Design. Zur hochwertigen Ausstattung der Bürofläche …', 'Das mit dem Architekturpreis ausgezeichnete Bürogebäude verbindet in gelungener Weise die Kombination aus Funktionalität und Design. Zur hochwertigen Ausstattung der Bürofläche zählen u.a. bodentiefe Fensterelemente, ein hochwertiger Parkett-/ und Teppichboden, Bodentanks, außenliegender Sonnenschutz auf der Westseite und innenliegender Sonnenschutz auf der Ostseite sowie Empfangsservice mit Concierge Service möglich. Bei dieser Fläche handelt es sich um eine Untervermietung bis 30.04.2028. Anschließend müssen Konditionen und Laufzeit neu verhandelt werden. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt. Pkw-Stellplätze können nach Rücksprache in der Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_25602.pdf', null, 'filemaker', '25602') on conflict (id) do nothing;
