insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21915')::uuid, md5('building-hamburger-strasse-11-22083')::uuid, '21915', 'moderne-bueroflaeche-mit-traumhaftem-blick-ueber-hamburg-21915', 'Moderne Bürofläche mit traumhaftem Blick über Hamburg', 'Der Mundsburg Office Tower befindet sich am EKZ Hamburger Meile mit seinen vielseitigen Einkaufsmöglichkeiten und zahlreichen Cafés und Restaurants. Die Anbindung an den ÖPNV ist …', 'Der Mundsburg Office Tower befindet sich am EKZ Hamburger Meile mit seinen vielseitigen Einkaufsmöglichkeiten und zahlreichen Cafés und Restaurants. Die Anbindung an den ÖPNV ist durch die gegenüber liegende U-Bahnstation Mundsburg sowie diverse Buslinien gesichert. Die modernisierte Bürofläche wird über ein großzügiges Foyer mit drei Personenaufzügen erschlossen. Zur aktuellen Ausstattung zählen Glaselemente, Teppichfußboden, Beleuchtungssysteme, Kühl- und Heizdecken für ein angenehmes Raumklima, außen liegender elektrischer Sonnenschutz, Bodentanks, Beleuchtungssysteme, hochwertige Sanitäranlagen und eine moderne Pantry. Pkw-Stellplätze können im angrenzenden Parkhaus angemietet werden. Die Innenansichten stammen aus einer ähnlichen Fläche im Gebäude.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], 181, 2125, 'https://www.buerohamburg.de/objects/pdf/BHI_21915.pdf', null, 'filemaker', '21915') on conflict (id) do nothing;
