insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25059')::uuid, md5('building-georgsplatz-1-20099')::uuid, '25059', 'ausbau-nach-mieterwunsch-bueroflaeche-direkt-am-hbf-25059', 'Ausbau nach Mieterwunsch: Bürofläche direkt am Hbf', 'Das Büro- und Geschäftshaus befindet sich in erstklassiger Lage in der Hamburger Innenstadt, zwischen Ballindamm und Mönckebergstraße, nur wenige Schritte vom Hauptbahnhof …', 'Das Büro- und Geschäftshaus befindet sich in erstklassiger Lage in der Hamburger Innenstadt, zwischen Ballindamm und Mönckebergstraße, nur wenige Schritte vom Hauptbahnhof entfernt. Das direkte Umfeld zeichnet sich durch zahlreiche Einkaufsmöglichkeiten und eine vielfältige Auswahl an Restaurants und Cafés aus. Zugleich ist die Anbindung an den öffentlichen Nahverkehr dank der unmittelbaren Nähe zum Hauptbahnhof hervorragend.  Die Raumaufteilung und Ausstattung der Bürofläche erfolgt in Abstimmung mit dem künftigen Mieter, um individuellen Wünschen gerecht zu werden. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer neuausgebauten Fläche im Objekt. Nach Rücksprache können in der hauseigenen Tiefgarage Pkw-Stellplätze angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 358, 426, 'https://www.buerohamburg.de/objects/pdf/BHI_25059.pdf', null, 'filemaker', '25059') on conflict (id) do nothing;
