insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-14143')::uuid, md5('building-holzmuehlenstrasse-84-88-22041')::uuid, '14143', 'buero-und-loftflaeche-in-ehemaliger-druckerei-14143', 'Büro- und Loftfläche in ehemaliger Druckerei', 'Das traditionelle Rotklinkergebäude des Architekten Höger befindet sich zwischen dem Friedrich-Ebert-Damm und der Walddörferstraße. Die Anbindung an den ÖPNV ist durch die …', 'Das traditionelle Rotklinkergebäude des Architekten Höger befindet sich zwischen dem Friedrich-Ebert-Damm und der Walddörferstraße. Die Anbindung an den ÖPNV ist durch die U-Bahnstation Straßburger Straße sowie eine nahe gelegene Bushaltestelle gewährleistet. Die helle Mietfläche verfügt über Teppichfußboden, Beleuchtungssysteme, ein Fensterbrüstungskanal für Verkabelung, getrennte WC-Einheiten und eine Pantry. Das Gebäude verfügt über ein repräsentatives Treppenhaus mit einem Personenaufzug. Ein Lastenaufzug ist ebenfalls vorhanden. Ein Seminarraum steht für alle Mieter im Haus kostenfrei zur Verfügung. PKW-Stellplätze stehen auf dem Hof zur Verfügung. Die Innenansichten stammen teilweise aus anderen Flächen im Gebäude. Der obige Mietpreis kann noch, je nach Ausstattungswünschen, variieren.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_14143.pdf', null, 'filemaker', '14143') on conflict (id) do nothing;
