insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25580')::uuid, md5('building-am-sandtorkai-70-73-20457')::uuid, '25580', 'individuelle-bueroflaeche-mit-blick-auf-die-elbphilharmonie-25580', 'Individuelle Bürofläche mit Blick auf die Elbphilharmonie', 'Das Vespucci Haus befindet sich in prominenter HafenCity-Lage am Museumshafen schräg gegenüber der berühmten Elbphilharmonie. Die Anbindung an das öffentliche Verkehrsnetz ist …', 'Das Vespucci Haus befindet sich in prominenter HafenCity-Lage am Museumshafen schräg gegenüber der berühmten Elbphilharmonie. Die Anbindung an das öffentliche Verkehrsnetz ist durch die nur wenige Meter entfernte U-Bahnstation Baumwall gesichert. Das Umfeld ist geprägt durch eine Vielzahl an Cafés und Restaurants. Auch die direkte Innenstadt, mit allen Geschäften des täglichen Bedarfs, ist nach kurzem Fußweg erreicht. Die helle Mietfläche wird über ein repräsentatives Foyer mit Personenaufzug erschlossen. Die vakanten Büroflächen werden in enger Abstimmung mit dem zukünftigen Mieter neu aufgeteilt und ausgestattet. Der Nettomietpreis variiert je nach Ausstattungswünschen ab Euro 27,00 pro qm zzgl. Nebenkosten und Mehrwertsteuer. Die Innenansichten stammen aus einer renovierten Mieteinheit im Gebäude. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], 428, 1599, 'https://www.buerohamburg.de/objects/pdf/BHI_25580.pdf', null, 'filemaker', '25580') on conflict (id) do nothing;
