insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23537')::uuid, md5('building-am-sandtorkai-70-73-20457')::uuid, '23537', 'moderne-bueroflaeche-mit-blick-auf-die-elbphilharmonie-23537', 'Moderne Bürofläche mit Blick auf die Elbphilharmonie', 'Das Vespucci Haus befindet sich in Hafen City-Lage am Museumshafen schräg gegenüber der Elbphilharmonie. Die Anbindung an das öffentliche Verkehrsnetz ist durch die nahe gelegene …', 'Das Vespucci Haus befindet sich in Hafen City-Lage am Museumshafen schräg gegenüber der Elbphilharmonie. Die Anbindung an das öffentliche Verkehrsnetz ist durch die nahe gelegene U- Bahnstation Baumwall gesichert. Diverse Cafés und Restaurants im direkten Umfeld sorgen für abwechslungsreiche Mittagspausen. Auch die Innenstadt ist fußläufig schnell erreicht. Die helle Bürofläche erschließt sich über ein Foyer mit Personenaufzug. Die hochwertige Ausstattung umfasst Bodentanks, Teppich- und Amtico- Bodenbelag, teilweise innen liegenden Sonnenschutz, Steh- und Deckenleuchten sowie teilweise Küchenzeilen. Die Bürofläche wird in Abstimmung mit dem zukünftigen Mieter aufgeteilt und ausgestattet. Die Innenansichten sind beispielhaft gewählt. PKW- Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], 428, 1599, 'https://www.buerohamburg.de/objects/pdf/BHI_23537.pdf', null, 'filemaker', '23537') on conflict (id) do nothing;
