insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19333')::uuid, md5('building-am-sandtorkai-38-41-20457')::uuid, '19333', 'ab-sofort-moderne-bueroflaeche-in-der-hafencity-19333', 'Ab sofort: moderne Bürofläche in der HafenCity', 'Das Columbus Haus bildet das Tor zur HafenCity. Der markante Turm besticht durch seine beeindruckende Glaskonstruktion und die außergewöhnliche Architektur. Die Hamburger City ist …', 'Das Columbus Haus bildet das Tor zur HafenCity. Der markante Turm besticht durch seine beeindruckende Glaskonstruktion und die außergewöhnliche Architektur. Die Hamburger City ist in wenigen Gehminuten erreicht. Die Anbindung an den ÖPNV ist durch die U-Bahn Stationen Baumwall und Rödingsmarkt gesichert. Im Umfeld befinden sich zahlreiche Cafés und Restaurants. Die helle und sehr hochwertig ausgestattete Bürofläche kann den individuellen Bedürfnissen des zukünftigen Mieters angepasst werden. Pkw-Stellplätze stehen zur Anmietung bereit. Die Innenansichten sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], 142, 1156, 'https://www.buerohamburg.de/objects/pdf/BHI_19333.pdf', null, 'filemaker', '19333') on conflict (id) do nothing;
