insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-9239')::uuid, md5('building-erste-brunnenstrasse-1-3-20459')::uuid, '9239', 'hochwertig-ausgestattete-bueroflaeche-am-hamburger-michel-9239', 'Hochwertig ausgestattete Bürofläche am Hamburger Michel', 'Das moderne Bürogebäude befindet sich unmittelbar am lebendigen und zentral gelegenen Großneumarkt mit seinen zahlreichen Restaurants, Cafés und Geschäften des täglichen Bedarfs. …', 'Das moderne Bürogebäude befindet sich unmittelbar am lebendigen und zentral gelegenen Großneumarkt mit seinen zahlreichen Restaurants, Cafés und Geschäften des täglichen Bedarfs. Die Anbindung an das öffentliche Verkehrsnetz ist nicht zuletzt durch die nahegelegenen U- und S-Bahnstationen Rödingsmarkt und Stadthausbrücke als sehr gut zu bezeichnen. Die lichtdurchflutete Mietfläche verfügt u.a. über bodentiefe Fensterelemente, z.T. Glastüren und Glasausschnitte in den Wänden, einen außenliegenden Sonnenschutz, einen Hohlraumboden sowie eine Pantry. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_9239.pdf', null, 'filemaker', '9239') on conflict (id) do nothing;
