insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-097')::uuid, md5('building-schottmuellerstrasse-20a-20251')::uuid, '097', 'das-hofbuero-moderne-architektur-in-eppendorf-097', 'Das Hofbüro - moderne Architektur in Eppendorf', 'In ruhiger Hoflage der Schottmüllerstraße befindet sich dieses halbrund gebaute moderne Bürogebäude im Herzen Eppendorfs. Das belebte Umfeld des Stadtteils bietet ein breites …', 'In ruhiger Hoflage der Schottmüllerstraße befindet sich dieses halbrund gebaute moderne Bürogebäude im Herzen Eppendorfs. Das belebte Umfeld des Stadtteils bietet ein breites gastronomisches Angebot und zahlreiche Geschäfte des täglichen Bedarfs. Im Objekt verbindet ein gläserner Aufzug die Geschosse einschließlich der Tiefgarage. Das Treppenhaus ist mit einem dunklen Steinboden und z.T. Sichtbeton versehen. Die sich im 2.OG befindende Bürofläche ist derzeit in 12 Büroräume unterteilt und verfügt über einen großzügigen Loungebereich. Zur Ausstattung zählt unter anderem ein hochwertiger Teppichbodenbelag, zahlreiche Glaselemente, Deckenbeleuchtung sowie in Bodentanks integrierte EDV-Verkabelung, separate WC-Einheiten sowie eine offene Küchenzeile.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-097-1')::uuid, md5('property-097')::uuid, 'Mietfläche', 437, 16.9, null, 'filemaker', '097-1') on conflict (id) do nothing;
