insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19532')::uuid, md5('building-holstenkamp-46a-22525')::uuid, '19532', 'individuelles-bueroloft-in-ruhigem-hinterhof-19532', 'Individuelles Büroloft in ruhigem Hinterhof', 'Die sehr vielseitig nutzbare Gewerbefläche befindet sich in ruhiger Hoflage im Stadtteil Bahrenfeld an der Grenze zu Altona. Gastronomische Einrichtungen sind fußläufig zu …', 'Die sehr vielseitig nutzbare Gewerbefläche befindet sich in ruhiger Hoflage im Stadtteil Bahrenfeld an der Grenze zu Altona. Gastronomische Einrichtungen sind fußläufig zu erreichen. Die Anbindung an die A7 und den ÖPNV ist durch den S-Bahnhof Diebsteich und diverse Buslinien gegeben. Zur aktuellen Ausstattung der Bürofläche zählen u.a. ein Parkettboden, Glaselemente, eine Einbauküche sowie getrennte WC-Einheiten. Besonderen Charme bekommt das Büro durch seine hohen Decken und den loftartigen Charakter. Zusätzlich ist ein Lastenaufzug vorhanden, welcher direkt in die Mietung fährt. Stellplätze können auf Anfrage angemietet weden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['lastenaufzug', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_19532.pdf', null, 'filemaker', '19532') on conflict (id) do nothing;
