insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24843')::uuid, md5('building-heidenkampsweg-73-79-20097')::uuid, '24843', 'repraesentatives-buerohaus-in-verkehrsguenstiger-lage-24843', 'Repräsentatives Bürohaus in verkehrsgünstiger Lage', 'Das moderne Bürogebäude befindet sich in markanter Lage in zentraler City-Süd Lage zwischen den Elbbrücken und der Hamburger City. Die Anbindung an den ÖPNV ist durch die …', 'Das moderne Bürogebäude befindet sich in markanter Lage in zentraler City-Süd Lage zwischen den Elbbrücken und der Hamburger City. Die Anbindung an den ÖPNV ist durch die S-Bahn-Station Hammerbrook gesichert. Auch die Autobahnzubringer sind in wenigen Fahrminuten erreicht. Gute Einkaufsmöglichkeiten und diverse Cafés und Restaurants im direkten Umfeld erhöhen die Attraktivität dieses Standortes. Die vakante Bürofläche kann nach den individuellen Bedürfnissen des Mieters neu ausgestattet und aufgeteilt werden. PKW-Stellplätze stehen in der hauseigenen Tiefgarage zur Anmietung bereit. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 443, 786, 'https://www.buerohamburg.de/objects/pdf/BHI_24843.pdf', null, 'filemaker', '24843') on conflict (id) do nothing;
