insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-1009')::uuid, md5('building-schnackenburgallee-175-179-22525')::uuid, '1009', 'solitaergebaeude-mit-loftcharakter-in-eidelstedt-1009', 'Solitärgebäude mit Loftcharakter in Eidelstedt', 'Der charmante und liebevoll restaurierte Gewerbehof befindet sich in verkehrsgünstiger Lage zwischen dem Volksparkstadion und der BAB 7 in unmittelbarer Nähe zur S-Bahnstation …', 'Der charmante und liebevoll restaurierte Gewerbehof befindet sich in verkehrsgünstiger Lage zwischen dem Volksparkstadion und der BAB 7 in unmittelbarer Nähe zur S-Bahnstation Eidelstedt. Die Mietfläche erstreckt sich über zwei Ebenen. Die Ausstattung umfasst teilweise Steinfliesen als auch Teppichbodenbelag und Holzfußboden, glatt gespachtelte Decken und Wände, EDV-Verkabelung, Sprossenfensterelemente, eine großzügige Teeküche sowie getrennte WC-Bereiche. Pkw-Stellplätze können nach Rücksprache angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['erdgeschoss', 'stellplaetze']::text[], 360, 447, 'https://www.buerohamburg.de/objects/pdf/BHI_1009.pdf', null, 'filemaker', '1009') on conflict (id) do nothing;
