insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-12760')::uuid, md5('building-am-sandtorkai-37-20457')::uuid, '12760', 'moderne-bueroflaeche-in-der-hafen-city-12760', 'Moderne Bürofläche in der Hafen-City', 'Das hochwertige Bürogebäude befindet sich in der Hamburger HafenCity und bietet einen schönen Blick auf die Speicherstadt und den Hamburger Hafen. Die Anbindung an das …', 'Das hochwertige Bürogebäude befindet sich in der Hamburger HafenCity und bietet einen schönen Blick auf die Speicherstadt und den Hamburger Hafen. Die Anbindung an das Verkehrsnetz ist sehr gut, die Autobahnanbindung ist schnell erreicht und die U-Bahnstation Baumwall liegt nur wenige Gehminuten entfernt. Diverse Restaurants und gute Einkaufsmöglichkeiten befinden sich im unmittelbaren Umfeld. Die vakante Bürofläche erschließt sich über ein repräsentatives Foyer mit drei Personenaufzügen. Die hochwertige Ausstattung umfasst Hohlraumboden mit einer CAT 7-Verkabelung, ca. 3,5 m hohe Decken, Stehleuchten, eine Pantry sowie getrennte WC-Bereiche. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Die Bilder stammen aus einer Fläche im Objekt. Pkw-Stellplätze können angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_12760.pdf', null, 'filemaker', '12760') on conflict (id) do nothing;
