insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19040')::uuid, md5('building-winterhuder-weg-76-22085')::uuid, '19040', 'moderne-bueroflaeche-mit-grosser-terrasse-in-winterhude-19040', 'Moderne Bürofläche mit großer Terrasse in Winterhude', 'Das gepflegte Objekt befindet sich in lebendiger Lage zwischen Uhlenhorst und Barmbek-Süd. Die Anbindung an den ÖPNV ist durch den nahe gelegenen U-Bahnhof Mundsburg sowie diverse …', 'Das gepflegte Objekt befindet sich in lebendiger Lage zwischen Uhlenhorst und Barmbek-Süd. Die Anbindung an den ÖPNV ist durch den nahe gelegenen U-Bahnhof Mundsburg sowie diverse Buslinien, welche in unmittelbarer Nähe des Objekts halten, gesichert. Das Einkaufszentrum Hamburger Meile mit zahlreichen Geschäften, Cafés und Restaurants ist nach wenigen Gehminuten erreicht. Das Gebäude wird über ein helles Foyer mit Personenaufzug erschlossen. Zur aktuellen Ausstattung der lichtdurchfluteten Bürofläche zählen ein Amticofußboden in Holzoptik, zahlreiche Glastrennwände, Beleuchtungssysteme, eine CAT-7-Verkabelung in Bodenkabelkanälen und Deckentrassen, ein klimatisierter Serverraum, außen liegender elektrischer Sonnenschutz, eine großzügige Küche mit Aufenthaltsmöglichkeit sowie getrennte WC-Einheiten. Highlight ist eine ca. 52 qm große Terrasse, welche zur oben genannten Größe addiert wird. Kostenfreie PKW-Stellplätze stehen im direkten Umfeld zur Verfügung, können aber auch je nach Verfügbarkeit auf dem Gelände angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['balkon-terrasse', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_19040.pdf', null, 'filemaker', '19040') on conflict (id) do nothing;
