insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24101')::uuid, md5('building-spitalerstrasse-1-20095')::uuid, '24101', 'repraesentatives-buero-und-geschaeftsgebaeude-in-erstklassiger-lage-24101', 'Repräsentatives Büro- und Geschäftsgebäude in erstklassiger Lage', 'In bester Lage direkt gegenüber dem Hamburger Hauptbahnhof und am Eingang zur beliebten Spitalerstraße mit vielfältigen Einkaufs-, Gastronomie- und Freizeitmöglichkeiten wurde das …', 'In bester Lage direkt gegenüber dem Hamburger Hauptbahnhof und am Eingang zur beliebten Spitalerstraße mit vielfältigen Einkaufs-, Gastronomie- und Freizeitmöglichkeiten wurde das um 1906 errichtete, ehemalige Lloyd-Hotel aufwendig saniert. Heute präsentiert sich das historische Gebäude als modernes und repräsentatives Büro- und Geschäftshaus.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24101-1')::uuid, md5('property-24101')::uuid, 'Mietfläche', 460, 29.5, null, 'filemaker', '24101-1') on conflict (id) do nothing;
