insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-645')::uuid, md5('building-kieler-strasse-303-22525')::uuid, '645', 'gepflegte-bueroflaeche-an-der-kieler-strasse-645', 'Gepflegte Bürofläche an der Kieler Straße', 'Das moderne Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage nur wenige Minuten von der A7 entfernt. Die S-Bahnstation Langenfelde und eine nahe gelegene …', 'Das moderne Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage nur wenige Minuten von der A7 entfernt. Die S-Bahnstation Langenfelde und eine nahe gelegene Bushaltestelle sind fußläufig schnell erreicht und sichern eine gute Anbindung an den ÖPNV. Zahlreiche Einkaufsmöglichkeiten und diverse Cafés und Restaurants im direkten Umfeld gewährleisten eine gute Nahversorgung. Das gepflegte Gebäude hat gerade einen neuen Fassadenanstrich erhalten. Die helle, nach modernem Standard ausgebaute  Bürofläche erschließt sich über ein lichtdurchflutetes Treppenhaus mit Personenaufzug. Die aktuelle Ausstattung umfasst LED Beleuchtung, EDV- Verkabelung, Teppichboden, eine Pantry und separate WC-Einheiten. Pkw-Stellplätze können am Objekt angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 330, 797, 'https://www.buerohamburg.de/objects/pdf/BHI_645.pdf', null, 'filemaker', '645') on conflict (id) do nothing;
