insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25581')::uuid, md5('building-schulterblatt-58-20357')::uuid, '25581', 'loftige-bueroflaeche-in-der-alten-pianofabrik-25581', 'Loftige Bürofläche in der Alten Pianofabrik', 'Das aufwendig restaurierte Fabrikgebäude Alte Pianofabrik befindet sich inmitten des lebendigen Schanzenviertels in ruhiger Hinterhoflage. Zahlreiche Restaurants, Szene-Kneipen, …', 'Das aufwendig restaurierte Fabrikgebäude Alte Pianofabrik befindet sich inmitten des lebendigen Schanzenviertels in ruhiger Hinterhoflage. Zahlreiche Restaurants, Szene-Kneipen, Cafés und Bars sowie alle Geschäfte des täglichen Bedarfs prägen das direkte Umfeld. Nach wenigen Fußminuten erreicht man den U- und S-Bahnhof Sternschanze sowie diverse Bushaltestellen.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25581-1')::uuid, md5('property-25581')::uuid, 'Mietfläche', 468, 18, null, 'filemaker', '25581-1') on conflict (id) do nothing;
